{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C02","C05","C10","C12","C13","C15","C19","C20","C22","C25","C26","C27","C29","C30","C31","C32","C33","C35"],
  "contradictory_card_ids": ["C23","C28"],
  "prediction_basis_card_ids": ["C02","C10","C31","C35","C12","C20","C33","C15","C25"],
  "claims": [
    {
      "claim": "Lefamulin, the closest structural context as a diterpene antibiotic, has fasted absolute F of 25.8% (C02, C10), confirmed by population PK Ftot of 0.24 in the fasted state (C31) and by the 600 mg oral versus 150 mg IV AUC geometric mean ratio of 103%, which dose-normalizes to about 25.8% (C35).",
      "card_ids": ["C02","C10","C31","C35"]
    },
    {
      "claim": "Polar rigid polycyclic lactones can be well absorbed: digitoxin fasted absolute F was 90.6% to 91.2% (C12, C20) with 89.7% AUC-based availability (C33), and topiramate F was above 80% (C15).",
      "card_ids": ["C12","C20","C33","C15"]
    },
    {
      "claim": "Small polar drugs also show high F: 5-ISMN about 100% (C25), doxifluridine 34% to 47% as capsules and 50% to 80% in rats (C26, C27), and clavulanic acid 98% in cats (C32).",
      "card_ids": ["C25","C26","C27","C32"]
    },
    {
      "claim": "The only sub-20% record, tacrolimus about 10% in fasted rats given a PEG solution (C28), is species and formulation specific and does not transfer because human tacrolimus F is about 20% (C13) and the query lacks tacrolimus extensive first-pass liability.",
      "card_ids": ["C28","C13"]
    },
    {
      "claim": "Dihydroartemisinin oral F of 45% in volunteers (C19, C22) supports adequate absorption for terpene lactones; the poor DHA outcome (C23) is solubility limited and does not transfer because the query solubility prior is favorable.",
      "card_ids": ["C19","C22","C23"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C25","C26","C27","C29","C30","C31","C32","C33","C34","C35","C36"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "No permeability, efflux, or first-pass measurements are available for the query.",
    "The query is more polar (logD -1.37, TPSA 148.8) than lefamulin and most transfer molecules, so transfer remains indirect.",
    "Tacrolimus rat data (C28) show species and formulation dependence that cannot be resolved for the query.",
    "No human data exist for the exact diterpene lactone scaffold."
  ],
  "decision_summary": "L2 records from the same contexts reinforce the L1 direction. Lefamulin population PK (C31) and AUC ratio (C35) confirm about 25% fasted F, digitoxin AUC (C33) confirms about 90%, and polar small molecules (C25, C26, C27, C32) show high F. The only sub-20% record (C28) is a rat PEG-solution tacrolimus value with low transferability and is not affirmative evidence for F below 20% in the query. The physicochemical prior remains a genuine uncertainty but is not endpoint proof. Prediction stays high with moderate confidence."
}

